import {toolBanner} from './tool-banner.mjs';
import {esc,icon} from './ui.mjs';

const mounts=new WeakMap();
const providerLabels={wechat:'微信支付',alipay:'支付宝'};
const statusLabels={pending:'待支付',paid:'支付成功',failed:'支付未完成',expired:'已过期',closed:'已关闭',refunded:'已退款'};
const pending=item=>item?.status==='pending';
const money=value=>Number.isSafeInteger(value)&&value>=0?'¥'+(value/100).toFixed(2):'金额待确认';
const date=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'时间未记录':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short',hour12:false}).format(d);};
const channelName=value=>providerLabels[value]||'支付渠道';
const checkoutHref=({productId,orderId}={})=>'#membership/pay'+(orderId?'?order='+encodeURIComponent(orderId):productId?'?product='+encodeURIComponent(productId):'');
const loginHref=()=>'/auth.html?mode=login&next='+encodeURIComponent(location.pathname+location.search+location.hash);

function stylesheet(){if(!document.getElementById('paperknow-payment-styles')){const link=document.createElement('link');link.id='paperknow-payment-styles';link.rel='stylesheet';link.href='/workspace/payment.css';document.head.append(link);}}
function heading(title,description,orders=false){if(orders)return toolBanner('orders',{title,description,extraClass:'payment-heading',actions:`<a class="btn secondary" href="${checkoutHref()}">${icon('diamond',16)}查看可购服务</a>`});return `<header class="payment-heading"><div><span class="payment-eyebrow">PAPERKNOW · CHECKOUT</span><h1>${title}</h1><p>${description}</p></div><a class="btn secondary" href="#orders">${icon('file',16)}我的订单</a></header>`;}
function login(){return `<section class="payment-card payment-empty">${icon('user',32)}<h2>登录后查看账户与支付订单</h2><p>订单和购买记录保存到你的 PaperKnow 账户，不会写入本地草稿。</p><a class="btn primary" href="${esc(loginHref())}">登录账户 ${icon('arrow',16)}</a></section>`;}
function retry(message){return `<section class="payment-card payment-empty">${icon('clock',32)}<h2>暂时无法读取支付信息</h2><p>${esc(message)}</p><button class="btn secondary" data-payment-retry>重新读取</button></section>`;}
function entitlementText(value){if(!value||typeof value!=='object')return '';const parts=[];if(value.type==='credits'&&Number.isSafeInteger(value.creditAmount)&&value.creditAmount>0)parts.push(`${value.creditAmount} 科研积分`);if(Number.isSafeInteger(value.quantity)&&value.quantity>0)parts.push(`${value.quantity} ${value.type==='credits'?'科研积分':value.type==='storage'?'存储额度':'份权益'}`);if(Number.isSafeInteger(value.durationDays)&&value.durationDays>0)parts.push(`有效期 ${value.durationDays} 天`);return parts.join(' · ');}

function lifecycle(container){
 if(!container)throw new Error('未找到支付页面容器');
 mounts.get(container)?.();stylesheet();
 let alive=true;const controllers=new Set(),timers=new Set(),listeners=[];
 const state={container,get alive(){return alive&&container.isConnected;},later(fn,delay){const id=setTimeout(()=>{timers.delete(id);if(state.alive)fn();},delay);timers.add(id);return id;},clear(id){clearTimeout(id);timers.delete(id);},listen(target,name,fn){target.addEventListener(name,fn);listeners.push([target,name,fn]);},abort(){for(const controller of controllers)controller.abort();controllers.clear();},async api(path,data){const controller=new AbortController();controllers.add(controller);const timeout=state.later(()=>controller.abort(),20000);try{const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});let value;try{value=await response.json();}catch{throw new Error('服务暂时无法响应，请稍后重试。');}if(!state.alive)throw new DOMException('页面已切换','AbortError');if(!response.ok){const error=new Error(value?.error||'请求未完成，请稍后重试。');error.status=response.status;throw error;}return value;}finally{state.clear(timeout);controllers.delete(controller);}},cleanup(){if(!alive)return;alive=false;state.abort();for(const id of timers)clearTimeout(id);timers.clear();for(const [target,name,fn] of listeners)target.removeEventListener(name,fn);if(mounts.get(container)===state.cleanup)mounts.delete(container);}};
 mounts.set(container,state.cleanup);
 state.listen(window,'hashchange',state.cleanup);
 return state;
}

async function defaultQRCode(content){const {toDataURL}=await import('../vendor/payment-qr.mjs');return toDataURL(content,{width:244,margin:2,errorCorrectionLevel:'M',color:{dark:'#12213aff',light:'#ffffffff'}});}

/** Mount a checkout using only the authenticated server catalogue and order state. */
export async function renderPaymentCheckout({productId,orderId,provider:preferredProvider,container=document.querySelector('.dashboard'),navigate,renderQRCode=defaultQRCode}={}){
 const state=lifecycle(container),q=selector=>container.querySelector(selector);
 let options={enabled:false,channels:[],products:[]},selectedProduct='',provider='',order=null,operation=0,paint=0,creating=false,querying=false,idempotencyKey='',pollTimer=null,tickTimer=null;
 const expired=()=>pending(order)&&Number.isFinite(Date.parse(order.expiresAt))&&Date.parse(order.expiresAt)<=Date.now();
 function stopTimers(){state.clear(pollTimer);state.clear(tickTimer);pollTimer=null;tickTimer=null;}
 function clearOrder(){operation++;state.abort();stopTimers();order=null;creating=false;querying=false;idempotencyKey='';}
 function notice(message,error=false){const target=q('[data-payment-notice]');if(target){target.textContent=message;target.classList.toggle('is-error',error);}}
 function channelReady(){return options.enabled&&options.channels.some(channel=>channel.provider===provider&&channel.ready===true);}
 function currentProduct(){return options.products.find(product=>product.id===selectedProduct);}
 function shell(){container.innerHTML=heading('安全支付','选择已开放的服务，使用微信或支付宝扫码付款。')+'<div class="payment-content"></div>';}
 function emptyCatalogue(){q('.payment-content').innerHTML=`<section class="payment-card payment-empty">${icon('shield',34)}<h2>可购服务正在准备中</h2><p>正式商品、价格和权益确认后会在这里展示。当前不会创建付款订单。</p><div class="payment-channel-preview">${['wechat','alipay'].map(channel=>`<span>${channelName(channel)}<small>${options.channels.some(item=>item.provider===channel&&item.ready)&&options.enabled?'渠道已配置':'暂未开通'}</small></span>`).join('')}</div><a class="btn secondary" href="#home">继续使用工作台</a></section>`;}
 function selection(message=''){
  stopTimers();const product=currentProduct();
  if(!options.products.length){emptyCatalogue();return;}
  q('.payment-content').innerHTML=`<div class="payment-checkout-grid"><section class="payment-card payment-selection"><div class="payment-section-heading"><span class="payment-step">01</span><div><h2>选择服务</h2><p>商品说明与价格由 PaperKnow 后台发布。</p></div></div><div class="payment-products" role="group" aria-label="可购服务">${options.products.map(item=>`<button type="button" class="payment-product ${item.id===selectedProduct?'is-selected':''}" data-payment-product="${esc(item.id)}" aria-pressed="${item.id===selectedProduct}"><span class="payment-product-title">${esc(item.title)}</span><strong>${money(item.priceCents)}</strong><span class="payment-product-description">${esc(item.description||'请在付款前确认服务说明。')}</span>${entitlementText(item.entitlement)?`<small>${esc(entitlementText(item.entitlement))}</small>`:''}${item.id===selectedProduct?`<i>${icon('check',14)}</i>`:''}</button>`).join('')}</div><div class="payment-section-heading payment-channel-heading"><span class="payment-step">02</span><div><h2>选择支付方式</h2><p>使用对应手机应用扫描支付二维码。</p></div></div><div class="payment-channels" role="group" aria-label="支付方式">${['wechat','alipay'].map(value=>{const ready=options.enabled&&options.channels.some(item=>item.provider===value&&item.ready===true);return `<button type="button" class="payment-channel ${value===provider?'is-selected':''}" data-payment-provider="${value}" aria-pressed="${value===provider}" ${ready?'':'disabled'}><span class="payment-provider-mark ${value}" aria-hidden="true">${value==='wechat'?'微':'支'}</span><span>${channelName(value)}<small>${ready?'扫码支付':'暂未开通'}</small></span>${value===provider?icon('check',17):''}</button>`;}).join('')}</div>${!options.enabled?'<p class="payment-inline-note">当前暂未开放收款，请稍后再试。</p>':''}</section><aside class="payment-card payment-summary"><span class="payment-eyebrow">订单确认</span><h2>${esc(product?.title||'请选择服务')}</h2><p>${esc(product?.description||'')}</p><dl><div><dt>${product?.entitlementType==='credits'?'到账积分':'购买数量'}</dt><dd>${product?.entitlementType==='credits'&&Number.isSafeInteger(product?.creditAmount)?product.creditAmount+' 科研积分':'1 份'}</dd></div><div><dt>支付方式</dt><dd>${provider?channelName(provider):'暂无可用渠道'}</dd></div></dl><div class="payment-total"><span>应付金额</span><strong>${money(product?.priceCents)}</strong></div><button type="button" class="btn primary" data-payment-create ${product&&channelReady()?'':'disabled'}>生成支付二维码 ${icon('arrow',16)}</button><p class="payment-notice" data-payment-notice role="status">${esc(message||'请核对服务说明和金额后扫码。二维码生成后不会自动扣款。')}</p><p class="payment-legal">付款前请阅读<a href="/terms/" target="_blank" rel="noopener">服务条款</a>与<a href="/privacy/" target="_blank" rel="noopener">隐私政策</a>。订单状态以服务器核验结果为准。</p></aside></div>`;
  container.querySelectorAll('[data-payment-product]').forEach(button=>button.onclick=()=>{if(button.dataset.paymentProduct===selectedProduct)return;clearOrder();selectedProduct=button.dataset.paymentProduct;selection();});
  container.querySelectorAll('[data-payment-provider]').forEach(button=>button.onclick=()=>{if(button.disabled||button.dataset.paymentProvider===provider)return;clearOrder();provider=button.dataset.paymentProvider;selection();});
  q('[data-payment-create]').onclick=createOrder;
 }
 function orderMarkup(){const localExpired=expired(),status=localExpired?'二维码已过期':statusLabels[order.status]||'状态待确认',paid=order.status==='paid';return `<section class="payment-card payment-order"><div class="payment-order-heading"><div><span class="payment-eyebrow">${paid?'PAYMENT COMPLETE':'SCAN TO PAY'}</span><h2>${esc(order.title)}</h2><p>订单号 <span>${esc(order.outTradeNo||order.id)}</span></p></div><span class="payment-status ${paid?'is-paid':localExpired?'is-expired':pending(order)?'is-pending':'is-closed'}">${status}</span></div><div class="payment-scan-layout"><div class="payment-qr-column"><div class="payment-qr" data-payment-qr>${paid?`<span class="payment-complete-icon">${icon('check',52)}</span>`:localExpired?`<span>${icon('clock',38)}<b>二维码已过期</b><small>请返回重新下单，付款记录可在我的订单查看。</small></span>`:pending(order)?'<span><b>正在准备二维码…</b></span>':`<span>${icon('file',38)}<b>${status}</b></span>`}</div><p class="payment-scan-instruction">${paid?'付款结果已经服务器核验。':pending(order)&&!localExpired?`请使用${channelName(order.provider)}扫一扫`:'可查询支付状态或前往我的订单核对。'}</p><p class="payment-expiry" data-payment-expiry></p></div><div class="payment-order-summary"><span>本次应付</span><strong>${money(order.amountCents)}</strong><dl><div><dt>支付方式</dt><dd>${channelName(order.provider)}</dd></div><div><dt>创建时间</dt><dd>${date(order.createdAt)}</dd></div>${order.expiresAt?`<div><dt>有效至</dt><dd>${date(order.expiresAt)}</dd></div>`:''}</dl>${paid?'<p class="payment-verified">'+icon('shield',17)+'已完成支付。已购买内容以订单和账户权益记录为准。</p>':'<p class="payment-inline-note">付款后状态会自动更新。请勿重复付款；暂未更新时可主动查询。</p>'}<div class="payment-order-actions">${paid?'':`<button type="button" class="btn primary" data-payment-query>查询支付状态</button>`}<a class="btn secondary" href="#orders">查看我的订单</a>${paid?'<a class="btn primary" href="#membership?scope=account">查看账户权益与积分</a>':`<button type="button" class="payment-text-button" data-payment-back>${pending(order)?'关闭支付窗口':'返回选择服务'}</button>`}</div><p class="payment-notice" data-payment-notice role="status"></p></div></div></section>`;}
 async function showOrder(){
  if(!state.alive||!order)return;stopTimers();const ticket=operation,itemId=order.id,rendering=++paint;q('.payment-content').innerHTML=orderMarkup();
  q('[data-payment-query]')?.addEventListener('click',()=>queryOrder(true));
  q('[data-payment-back]')?.addEventListener('click',()=>{const wasPending=pending(order);clearOrder();selection(wasPending?'支付窗口已关闭。尚未支付的订单仍可在“我的订单”查看和继续支付。':'请选择需要购买的服务。');});
  if(pending(order)&&!expired()){
   tick();schedulePoll();
   try{if(!order.qrContent||typeof order.qrContent!=='string'||order.qrContent.length>4096)throw new Error('支付二维码暂不可用，请查询订单状态或重新下单。');const imageURL=await renderQRCode(order.qrContent);if(!state.alive||ticket!==operation||rendering!==paint||order?.id!==itemId||!pending(order)||expired())return;if(typeof imageURL!=='string'||!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(imageURL))throw new Error('二维码显示失败，请重试。');const image=document.createElement('img');image.src=imageURL;image.alt=`使用${channelName(order.provider)}扫描支付二维码`;image.width=244;image.height=244;q('[data-payment-qr]')?.replaceChildren(image);}catch(error){if(state.alive&&ticket===operation)notice(error.message,true);}
  }
 }
 function tick(){if(!state.alive||!pending(order))return;if(expired()){void showOrder();return;}const target=q('[data-payment-expiry]');if(target&&order.expiresAt){const seconds=Math.max(0,Math.ceil((Date.parse(order.expiresAt)-Date.now())/1000));target.textContent=Number.isFinite(seconds)?`二维码剩余 ${Math.floor(seconds/60)} 分 ${String(seconds%60).padStart(2,'0')} 秒`:'';}tickTimer=state.later(tick,1000);}
 function schedulePoll(){state.clear(pollTimer);if(!state.alive||!pending(order)||expired()||document.hidden)return;pollTimer=state.later(()=>queryOrder(false),5000);}
 async function queryOrder(manual=false){if(!state.alive||!order||querying||(!manual&&(document.hidden||!pending(order)||expired())))return;querying=true;state.clear(pollTimer);const ticket=operation,id=order.id,button=q('[data-payment-query]');if(button)button.disabled=true;try{const data=await state.api('/orders/'+encodeURIComponent(id)+'/query',{});if(!state.alive||ticket!==operation||order?.id!==id)return;if(!data.item||data.item.id!==id)throw new Error('订单状态暂时无法更新，请稍后查询。');const changed=data.item.status!==order.status||data.item.qrContent!==order.qrContent||data.item.expiresAt!==order.expiresAt;order=data.item;if(changed)await showOrder();if(manual)notice(pending(order)?'已核对，订单尚未支付。如已付款，请稍后再次查询。':'订单状态已更新。');}catch(error){if(state.alive&&ticket===operation&&error.name!=='AbortError'){if(error.status===401){clearOrder();q('.payment-content').innerHTML=login();}else notice(manual?error.message:'状态暂时无法更新，可稍后主动查询。',true);}}finally{if(state.alive&&ticket===operation){querying=false;const current=q('[data-payment-query]');if(current)current.disabled=false;schedulePoll();}}}
 async function createOrder(){
  if(creating||!state.alive||!currentProduct()||!channelReady())return;creating=true;const ticket=operation;const button=q('[data-payment-create]');button.disabled=true;button.textContent='正在创建订单…';notice('正在与支付渠道建立订单，请稍候。');
  try{idempotencyKey||=crypto.randomUUID();const data=await state.api('/orders',{productId:selectedProduct,provider,idempotencyKey});if(!state.alive||ticket!==operation)return;if(!data.item?.id)throw new Error('订单未能完成创建，请重试。');order=data.item;await showOrder();}catch(error){if(!state.alive||ticket!==operation||error.name==='AbortError')return;if(error.status===401)q('.payment-content').innerHTML=login();else notice(error.message,true);}finally{if(state.alive&&ticket===operation){creating=false;const current=q('[data-payment-create]');if(current){current.disabled=!channelReady();current.innerHTML='生成支付二维码 '+icon('arrow',16);}}}
 }
 async function load(){
  shell();q('.payment-content').innerHTML='<section class="payment-card payment-empty" role="status">正在读取账户与支付信息…</section>';
  try{const account=await state.api('/auth/me');if(!account.user){q('.payment-content').innerHTML=login();return;}const response=await state.api('/payments/options');options={enabled:response.enabled===true,channels:Array.isArray(response.channels)?response.channels:[],products:Array.isArray(response.products)?response.products.filter(item=>item&&typeof item.id==='string'&&Number.isSafeInteger(item.priceCents)&&item.priceCents>0&&item.currency==='CNY'):[]};if(!state.alive)return;selectedProduct=productId?(options.products.some(item=>item.id===productId)?productId:''):options.products[0]?.id||'';provider=['wechat','alipay'].includes(preferredProvider)?preferredProvider:options.channels.find(item=>['wechat','alipay'].includes(item.provider)&&item.ready===true)?.provider||'';if(orderId){const data=await state.api('/orders/'+encodeURIComponent(orderId));if(!data.item?.id)throw new Error('没有找到这笔订单。');order=data.item;await showOrder();}else selection(productId&&!selectedProduct?'所选商品暂不可购买，请重新选择已开放的服务。':'');}catch(error){if(!state.alive||error.name==='AbortError')return;if(error.status===401){q('.payment-content').innerHTML=login();return;}q('.payment-content').innerHTML=retry(error.message);q('[data-payment-retry]').onclick=load;}
 }
 state.listen(document,'visibilitychange',()=>{state.clear(pollTimer);if(!document.hidden&&pending(order)){if(expired())void showOrder();else schedulePoll();}});
 await load();return state.cleanup;
}

/** Orders are always fetched from the authenticated account; no local demo records. */
export async function renderPaymentOrders({container=document.querySelector('.dashboard'),navigate}={}){
 const state=lifecycle(container),q=selector=>container.querySelector(selector);let loading=false;
 const go=href=>navigate?navigate(href):location.hash=href;
 async function load(){if(loading||!state.alive)return;loading=true;const refresh=q('[data-orders-refresh]');if(refresh)refresh.disabled=true;try{const account=await state.api('/auth/me');if(!account.user){container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+login();return;}const data=await state.api('/orders');const items=Array.isArray(data.items)?data.items:[];container.innerHTML=heading('我的订单','订单状态与金额来自服务器记录。请勿对同一笔订单重复付款。',true)+`<section class="payment-card payment-history"><header><div><h2>账户订单 <span>${items.length}</span></h2><p>微信支付与支付宝订单统一查看。</p></div><button type="button" class="btn secondary" data-orders-refresh>${icon('clock',15)}刷新订单</button></header>${items.length?`<div class="payment-order-list">${items.map(item=>`<article class="payment-history-item"><div class="payment-history-main"><span class="payment-provider-mark ${item.provider==='wechat'?'wechat':'alipay'}" aria-hidden="true">${item.provider==='wechat'?'微':'支'}</span><div><h3>${esc(item.title)}</h3><p>${channelName(item.provider)} · ${date(item.createdAt)}</p><small>订单号 ${esc(item.outTradeNo||item.id)}</small></div></div><div class="payment-history-state"><strong>${money(item.amountCents)}</strong><span class="payment-status ${item.status==='paid'?'is-paid':pending(item)?'is-pending':'is-closed'}">${statusLabels[item.status]||'状态待确认'}</span></div><button type="button" class="btn secondary" data-payment-order="${esc(item.id)}">${pending(item)?'继续支付':'查看订单'}</button></article>`).join('')}</div>`:`<div class="payment-empty">${icon('file',32)}<h3>还没有订单</h3><p>这里会展示你的真实购买记录。</p><a class="btn secondary" href="${checkoutHref()}">查看可购服务</a></div>`}<p class="payment-history-note">如对订单有疑问，请联系 <a href="mailto:contact@oneshowailab.com">contact@oneshowailab.com</a> 并提供订单号，请勿发送支付密码。</p></section>`;q('[data-orders-refresh]').onclick=load;container.querySelectorAll('[data-payment-order]').forEach(button=>button.onclick=()=>go(checkoutHref({orderId:button.dataset.paymentOrder})));}catch(error){if(!state.alive||error.name==='AbortError')return;container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+(error.status===401?login():retry(error.message));q('[data-payment-retry]')?.addEventListener('click',load);}finally{loading=false;const button=q('[data-orders-refresh]');if(button)button.disabled=false;}}
 container.innerHTML=heading('我的订单','查看你在 PaperKnow 账户中的真实购买记录。',true)+'<section class="payment-card payment-empty" role="status">正在读取订单…</section>';
 await load();return state.cleanup;
}

export function disposePayment(container=document.querySelector('.dashboard')){if(container)mounts.get(container)?.();}
